'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var isNaNArray = require( '@stdlib/assert/is-nan-array' );
var Float64Array = require( '@stdlib/array/float64' );
var abs = require( '@stdlib/math/base/special/abs' );
var sqrt = require( '@stdlib/math/base/special/sqrt' );
var ldexp = require( '@stdlib/math/base/special/ldexp' );
var EPS = require( '@stdlib/constants/float64/eps' );
var SMALLEST_NORMAL = require( '@stdlib/constants/float64/smallest-normal' );
var PI = require( '@stdlib/constants/float64/pi' );
var tryRequire = require( '@stdlib/utils/try-require' );
var largeAsym = require( './fixtures/cpp/large_asym.json' );
var smallAB = require( './fixtures/cpp/small_ab.json' );
var mediumAB = require( './fixtures/cpp/medium_ab.json' );
var largeRangeAB = require( './fixtures/cpp/large_range_ab.json' );
var intAB = require( './fixtures/cpp/int_ab.json' );


// VARIABLES //

var kernelBetainc = tryRequire( resolve( __dirname, './../lib/native.js' ) );
var opts = {
	'skip': ( kernelBetainc instanceof Error )
};


// FIXTURES //

var fixtures = require( './fixtures/cpp/output.json' );
var lowerRegularized = fixtures.lower_regularized;
var lowerUnregularized = fixtures.lower_unregularized;
var upperRegularized = fixtures.upper_regularized;
var upperUnregularized = fixtures.upper_unregularized;
var derivativeRegularized = fixtures.derivative_regularized;
var x = fixtures.x;
var a = fixtures.a;
var b = fixtures.b;


// TESTS //

tape( 'main export is a function', opts, opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof kernelBetainc, 'function', 'main export is a function' );
	t.end();
});

tape( 'attached to the function is a method which supports supplying a destination array', opts, opts, function test( t ) {
	var out;
	var v;

	out = [ 0.0, 0.0 ];
	v = kernelBetainc( 0.5, 1.0, 1.0, true, true, out, 1, 0 );

	t.strictEqual( v instanceof Float64Array, true, 'returns a Float64Array' );
	t.strictEqual( v.length, 2, 'returned array has two elements' );

	t.end();
});

