tape( 'the function returns the correct derivative for a naive analytical check', opts, function test( t ) {
	var expected;
	var delta;
	var tol;
	var val;

	val = kernelBetainc( 0.5, 2, 3, true, false );
	expected = 1.5;
	delta = abs( val[ 1 ] - expected );
	tol = 200.0 * EPS * abs( expected );
	t.ok( delta <= tol, 'within tolerance. Δ: '+delta+'. tol: '+tol );

	t.end();
});

tape( 'the function handles tiny parameter values', opts, function test( t ) {
	var small;
	var tiny;
	var val;

	tiny = SMALLEST_NORMAL / 2.0;
	small = EPS;
	if ( tiny !== 0.0 ) {
		val = kernelBetainc( small, tiny, small, true, false );
		t.strictEqual( val[ 0 ], 1.0, 'ibeta(tiny, eps, eps) = 1 where tiny = smallest_normal/2' );
	}

	val = kernelBetainc( 0.0, 2, 1, true, false );
	t.strictEqual( val[ 0 ], 0.0, 'return expected lower regularized value.' );

	val = kernelBetainc( 0.0, 1, 2, true, false );
	t.strictEqual( val[ 0 ], 0.0, 'return expected lower regularized value.' );

	t.end();
});

tape( 'the function evaluates the lower regularized incomplete beta function', opts, function test( t ) {
	var expected;
	var delta;
	var tol;
	var i;
	var y;

	expected = lowerRegularized;
	for ( i = 0; i < x.length; i++ ) {
		y = kernelBetainc( x[i], a[i], b[i], true, false )[0];
		if ( y === expected[i] ) {
			t.strictEqual( y, expected[i], 'x: '+x[i]+', y: '+y+'. a: '+a[i]+'. b: '+b[i]+', expected: '+expected[i] );
		} else {
			delta = abs( y - expected[ i ] );
			tol = 50.0 * EPS * abs( expected[ i ] );
			t.ok( delta <= tol, 'within tolerance. x: '+x[i]+'. a: '+a[i]+'. b: '+b[i]+'. y: '+y+'. E: '+expected[i]+'. Δ: '+delta+'. tol: '+tol );
		}
	}
	t.end();
});

